css:
.purubutton {
  width: 100%;
  height: auto;
}

.purubutton__fixed {
  width: 100%;
  max-width: 250px;
  height: auto;
  position: fixed;
  left: 50%;
  bottom: 10px;
  transform: translate(-50%, calc(100% + 10px));
  transition: transform 0.5s ease;
}

.purubutton.is-active .purubutton__fixed {
  transform: translate(-50%, 0);
}

.purubutton__link {
  width: 100%;
  height: auto;
  display: block;
}

.purubutton.is-active .purubutton__link {
  animation: puyoBtn 1.6s ease-in infinite;
}

img {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

@keyframes puyoBtn {
  0% {
    transform: scale(1.09);
  }

  10% {
    transform: scale(1.09);
  }

  30% {
    transform: scale(1.01);
  }

  40% {
    transform: scale(1.01);
  }

  50% {
    transform: scale(1, 1.04);
  }

  60% {
    transform: scale(1.09);
  }

  70% {
    transform: scale(1.02);
  }

  100% {
    transform: scale(1.09);
  }
}

.EDITABLE .purubutton__fixed {
  transform: translate(-50%, 0)
}

 .linkbox {
  width: 100%;
  margin: 0 auto 40px;
  padding: 0 15px;
  text-align: center;
  box-sizing: border-box;
}

 .linkbox input {
  display: none;
}

 .linkbox input+label,
 .linkbox>a {
  cursor: pointer;
  border: none;
  display: block;
  padding: 10px;
  text-decoration: none !important;
}

 .linkbox input+label .btn,
 .linkbox>a .btn {
  color: #fff;
  font-size: clamp(19px, 5.5vw, 34px);
  border: none;
  border-radius: 10px;
  box-shadow: 0 10px 0 #000;
  padding: 10px;
  font-weight: bold;
  background-color: #3f3f3f;
  line-height: 1.6;
  position: relative;
  display: block;
  transition: background-color 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

 .linkbox input:checked+label .btn,
 .linkbox>a .btn:hover {
  background-color: #bc0a1f;
  box-shadow: 0 10px 0 #7d1521;
}

 .linkbox input+label .btn:focus {
  outline: none !important;
}

 .linkbox.btn-two label,
 .linkbox.btn-two>a {
  width: 48%;
  box-sizing: border-box;
  display: inline-block;
}

.puyoBtn__box {
  width: 100%;
  height: auto;
  font-size: min(3vw, 16px);
  background-image: url(/uploads/b2a43120a9b3ac8e0801d4e9ae6c5efa881a7761649f09dc97fdcfb7457d78f1.png);
  background-size: 100%;
  aspect-ratio: 348/235;
  position: relative;
}

.puyoBtn__box a {
  width: calc(85% - 1em);
  height: auto;
  display: block;
  margin: 0 auto;
  padding: 0.4em 1em 0.4em 0;
  text-decoration: none;
  border-radius: 10vw;
  color: #fff;
  font-size: 1.6em;
  font-weight: bold;
  text-align: center;
  background-color: #a6c0fe;
  background-image: linear-gradient(120deg, #a6c0fe 0%, #f68084 100%);
  position: absolute;
  bottom: 2em;
  left: 50%;
  transform: scale(1) translateX(-50%);
  transform-origin: 0;
  animation: puyoBtnAnime 2s ease-in-out infinite;
}

.puyoBtn__box a:before {
  content: '';
  width: 1.5em;
  height: 1.5em;
  border-radius: 0.75em;
  background: #fff;
  display: block;
  position: absolute;
  top: 50%;
  right: 0.6em;
  transform: translateY(-50%);
}

.puyoBtn__box a:after {
  content: '';
  display: inline-block;
  width: 0.625em;
  height: 0.875em;
  background: #f68084;
  clip-path: polygon(0 0, 0 100%, 100% 50%);
  position: absolute;
  top: 50%;
  right: 0.95em;
  transform: translateY(-50%);
}

@keyframes puyoBtnAnime {

  0%,
  20%,
  40%,
  100% {
    transform: scale(1) translatex(-50%);
  }

  10%,
  30% {
    transform: scale(1.1) translatex(-50%);
  }
}

.btn-gold {
  width: 330px;
  font-family: "ヒラギノ明朝 Pro W3", "Hiragino Mincho Pro",
    "Hiragino Mincho ProN", "HGS明朝E", "ＭＳ Ｐ明朝", serif;
  display: inline-block;
  padding: 2px;
  border-radius: 5px;
  background-image: linear-gradient(315deg,
      #704308 0%,
      #ffce08 37%,
      #fefeb2 47%,
      #fafad6 50%,
      #fefeb2 53%,
      #e1ce08 63%,
      #704308 100%);
}

.btn {
  font-weight: 600;
  line-height: 1.5;
  position: relative;
  display: block;
  padding: 16px 0;
  cursor: pointer;
  transition: all 0.3s;
  text-align: center;
  vertical-align: middle;
  letter-spacing: 0.1em;
  text-decoration: none !important;
  color: #212529 !important;
  border-radius: 5px;
  background-color: #FFF;
}

.btn-text {
  font-size: 32px;
  background: linear-gradient(to top, #ffffdb, #a16422);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.btn-gold:hover .btn {
  text-shadow: 0 0 15px rgba(250, 250, 214, 0.5),
    0 0 15px rgba(250, 250, 214, 0.5), 0 0 15px rgba(250, 250, 214, 0.5),
    0 0 15px rgba(250, 250, 214, 0.5);
}

.layout.center {
  text-align: center;
}

.layout.right {
  text-align: right;
}

* {
  box-sizing: border-box;
}

.btn__area {
  text-align: center;
}

.btn {
  font-size: min(3vw, 16px);
  font-weight: 700;
  line-height: 1.5;
  padding: calc(1.5em - 12px) 3em 1.5em;
  position: relative;
  display: inline-block;
  cursor: pointer;
  user-select: none;
  transition: all 0.3s;
  text-align: center;
  vertical-align: middle;
  text-decoration: none;
  letter-spacing: 0.1em;
  color: #212529;
  background: #fff;
  border-radius: 0.5em;
}

.btn:before {
  position: absolute;
  top: -6px;
  left: -6px;
  width: 100%;
  height: 100%;
  content: "";
  transition: all 0.3s ease;
  border: 3px solid #000;
  border-radius: 0.5em;
}

.btn:hover {
  padding: calc(1.5em - 6px) 3em;
}

.btn:hover:before {
  top: 0;
  left: 0;
}

.btn {
  border-radius: 100vh;
}

.btn:before {
  border-radius: 100vh;
  -webkit-box-shadow: 3px 3px 0 #78e5e5;
  box-shadow: 3px 3px 0 #78e5e5;
}

.ctaBtn__area {
  width: 100%;
  height: auto;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 1em;
  font-size: min(3vw, 16px);
}

.ctaBtn__area,
.ctaBtn__area * {
  box-sizing: border-box;
}

.ctaBtn__area .btn {
  width: calc(50% - 1em);
  height: auto;
  border-radius: 3vw;
  padding: 0.4em 0.8em;
  text-decoration: none;
  color: #fff;
  font-weight: bold;
  font-size: 1.2em;
  text-align: center;
  box-shadow: 2px 2px 15px rgba(0, 0, 0, 0.2);
  transition: .3s ease-in-out;
  background-color: #000;
}

.ctaBtn__area .btn:hover {
  filter: brightness(1.1);
}

.ctaBtn__area .cl_orange {
  background-color: #EDAD0B;
}

.ctaBtn__area .cl_blue {
  background-color: #007FB1;
}

.ctaBtn__area .cl_purple {
  background-color: #5D639E;
}

.ctaBtn__area .cl_red {
  background-color: #C7243A;
}

.innerBtn__area {
  width: 100%;
  height: auto;
  position: relative;
}

.parentImg {
  width: 100%;
  height: auto;
}

.parentImg img {
  width: 100%;
  height: auto;
}

.childrenBtn {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  width: 90%;
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  flex-wrap: wrap;
}

.btn {
  width: calc((100% / 2) - 10px);
  margin: 10px 5px 0;
  display: block;
  text-decoration: none;
  border-radius: 0px;
  position: relative;
  outline: none;
  overflow: hidden;
  z-index: 2;
}

.btn img {
  width: 100%;
  height: auto;
}


.shine .btn:hover:before {
  content: '';
  position: absolute;
  top: 0;
  left: -75%;
  width: 50%;
  height: 100%;
  background: linear-gradient(to right, rgba(255, 255, 255, 0) 0%, rgba(255, 255, 255, .3) 100%);
  transform: skewX(-25deg);
  z-index: 2;
}

.shine .btn:hover::before {
  animation-name: shine;
  animation-duration: 0.7s;
  animation-iteration-count: infinite;
}

.big .btn:hover {
  animation-name: big;
  animation-duration: 0.7s;
  animation-fill-mode: forwards;
  animation-iteration-count: infinite;
}

@keyframes shine {
  100% {
    left: 125%;
  }
}

@keyframes big {
  0% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.05);
  }

  100% {
    transform: scale(1);
  }
}

.widget-container {
  font-size: 14px;
  width: min(750px, 100%);
  margin-inline: auto;
}

@media (max-width: 500px) {
  .widget-container {
    font-size: 3vw;
  }
}

.widget-container>* {
  box-sizing: border-box;
}

button {
  cursor: pointer;
  border: solid 1px #000;
  display: block;
  width: 100%;
  text-align: center;
  color: #FFF;
  font-weight: 600;
  background-color: #05337f;
  padding: 1em;
  line-height: 1.5;
  position: relative;
  box-shadow: 3px 3px 5px 0px rgba(0, 0, 0, 0.3);
}

button::before,
button::after {
  content: "";
  width: 1em;
  aspect-ratio: 1;
  position: absolute;
  top: 50%;
  right: 1.5em;
  transform: translateY(-50%);
  z-index: 5;
}

button::after {
  width: 2em;
  background-color: #FFF;
  border-radius: 50%;
  z-index: 1;
  right: 1em;
}

button::before {
  content: "";
  aspect-ratio: 1;
  clip-path: polygon(20% 0%, 0% 20%, 30% 50%, 0% 80%, 20% 100%, 50% 70%, 80% 100%, 100% 80%, 70% 50%, 100% 20%, 80% 0%, 50% 30%);
  background-color: #05337f;
  transform: translateY(-50%) rotate(135deg);
  transition: rotate 0.3s;
}

button.toggle::before {
  clip-path: polygon(0 35%, 100% 35%, 100% 65%, 0 65%);
  transform: translateY(-50%) rotate(0deg);
}

button.hidden {
  display: none;
}

.more-content {
  opacity: 0;
  max-height: 0;
  overflow: hidden;
  transition: all 0.3s;
}

button.hidden+.more-content,
button.toggle+.more-content {
  opacity: 1;
  max-height: 9999px;
  overflow: visible;
}



@media (min-width: 500px) {
  .sp-only {
    display: none;
  }
}

img,
video {
  width: 100%;
  height: auto;
}

* {
  box-sizing: border-box;
}

.conversation__area p {
  margin: 0;
}

.conversation__area {
  width: 100%;
  height: auto;
  position: relative;
  background: #cbe1ec;
  font-size: 16px;
  padding: 1em;
}

@media screen and (max-width: 600px) {
  .conversation__area {
    font-size: 12px;
  }
}

.conversation__headBox {
  position: absolute;
  top: -1.5em;
  left: 1em;
}

.conversation__headBox .head {
  color: #fff;
  font-size: 1.15em;
  font-weight: bold;
  background: #45A1CF;
  padding: 0.5em 1em;
}

.conversation__bubbleBox {
  display: flex;
  align-items: flex-start;
  margin-top: 1em;
}

.conversation__bubbleBox._right {
  justify-content: flex-end;
}

.conversation__bubbleBox._left {
  justify-items: flex-start;
}

.conversation__bubbleBox .bubble {
  width: auto;
  max-width: calc(60% - 2em);
  height: auto;
  border: 2px solid #aaa;
  border-radius: 5px;
  background: #fff;
  padding: 1em;
  position: relative;
}

.conversation__bubbleBox._right .bubble {
  order: 1;
  margin-right: 4.5%;
}

.conversation__bubbleBox._left .bubble {
  order: 2;
  margin-left: 4.5%;
}

.conversation__bubbleBox .bubble:before,
.conversation__bubbleBox .bubble:after {
  content: '';
  width: 0;
  height: 0;
  border-style: solid;
  position: absolute;
}

.conversation__bubbleBox .bubble::before {
  top: calc(1em - 2px);
}

.conversation__bubbleBox .bubble:after {
  top: 1em;
}

.conversation__bubbleBox._right .bubble:before {
  border-width: 9px 0 9px 15.6px;
  border-color: transparent transparent transparent #AAAAAA;
  right: -16px;
}

.conversation__bubbleBox._left .bubble:before {
  border-width: 9px 15.6px 9px 0;
  border-color: transparent #AAAAAA transparent transparent;
  left: -16px;
}

.conversation__bubbleBox._right .bubble:after {
  border-width: 7px 0 7px 12.1px;
  border-color: transparent transparent transparent #FFFFFF;
  right: -12px;
}

.conversation__bubbleBox._left .bubble:after {
  border-width: 7px 12.1px 7px 0;
  border-color: transparent #FFFFFF transparent transparent;
  left: -12px;
}

.conversation__bubbleBox .icon {
  width: 15%;
}

.conversation__bubbleBox._right .icon {
  order: 2;
}

.conversation__bubbleBox._left .icon {
  order: 1;
}

.conversation__bubbleBox .icon img {
  width: 100%;
  height: auto;
  object-fit: cover;
  border: 2px solid #ccc;
  border-radius: 10vw;
  aspect-ratio: 1/1;
}

.conversation__bubbleBox .icon .name {
  font-size: 0.9em;
  color: #666;
  text-align: center;
}

.conversation__whileBox {
  margin-top: 1em;
  width: 100%;
  height: auto;
}

.conversation__whileBox .while {
  font-size: 1.5em;
  color: #666;
}

.column-box {
  width: 100%;
  background-color: #000000;
  margin: 0 auto;
  padding: 40px 20px 50px;
  display: flex;
  align-items: stretch;
  justify-content: center;
  box-sizing: border-box;
}

.column-box .item-left {
  width: 100%;
  max-width: min(58vw, 540px);
}

.column-box .item-right {
  width: 100%;
  max-width: min(30vw, 250px);
  margin-left: 4%;
}

.bubble {
  color: #ffffff;
  font-size: min(3vw, 18px);
  line-height: 1.5;
  letter-spacing: 0.05em;
  text-align: center;
  white-space: nowrap;
  margin: 0 0 3px;
}

.link-btn {
  color: #ffffff !important;
  text-decoration: none !important;
  font-size: min(4.5vw, 27px);
  line-height: 1;
  white-space: nowrap;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.2em;
  padding: 0.5em 1em 0.5em 0.5em;
  min-height: min(3em, 70px);
  position: relative;
  background: linear-gradient(132deg, #4c4c4c 0%, #2c2c2c 100%);
  border-radius: 4px;
  box-shadow: inset 4px 4px 6px #474747, inset -4px -4px 6px #111111;
  overflow: hidden;
  box-sizing: border-box;
}

.link-btn::after {
  content: "";
  width: 0.25em;
  height: 0.25em;
  border-top: 1px solid #ffffff;
  border-right: 1px solid #ffffff;
  transform: rotate(45deg);
  position: absolute;
  top: calc(50% - 0.2em);
  right: 0.5em;
}

.link-btn.orange {
  background: linear-gradient(132deg, #f17432 0%, #ff6600 100%);
  box-shadow: inset 4px 4px 6px #f3c5bd, inset -4px -4px 6px #c72200;
}

.link-btn.blue {
  background: linear-gradient(132deg, #2989d8 0%, #207cca 100%);
  box-shadow: inset 4px 4px 6px #7db9e8, inset -4px -4px 6px #1e5799;
}

.icon {
  padding-bottom: 0.2em;
  flex-shrink: 0;
}

.icon svg {
  width: auto;
  height: 1em !important;
  fill: #ffffff;
  vertical-align: bottom;
}

.icon picture,
.icon img,
.icon video {
  display: inline-block;
  width: auto;
  height: 1em !important;
  vertical-align: bottom;
}

.link-btn.shiny:before {
  position: absolute;
  content: '';
  display: inline-block;
  top: -180px;
  left: 0;
  width: 30px;
  height: 100%;
  background-color: #ffffff;
  animation: shiny-brite 3s ease-in-out infinite;
}

@keyframes shiny-brite {
  0% {
    transform: scale(0) rotate(45deg);
    opacity: 0;
  }

  80% {
    transform: scale(0) rotate(45deg);
    opacity: 0.5;
  }

  81% {
    transform: scale(4) rotate(45deg);
    opacity: 1;
  }

  100% {
    transform: scale(50) rotate(45deg);
    opacity: 0;
  }
}

.btn-text-content {
  font-size: 16px;
  line-height: 1.35;
  width: min(620px, 90%);
  margin-inline: auto;
}

@media (max-width: 500px) {
  .btn-text-content {
    font-size: 2.8vw;
  }

  .title {
    font-size: 1em;
  }
}

.title {
  text-align: center;
  color: #042356;
  font-size: 1.25em;
  font-weight: 700;
}

.title span {
  display: inline-block;
  position: relative;
  padding-inline: 1.25em;
}

.title span::before,
.title span::after {
  content: "";
  display: inline-block;
  position: absolute;
  top: 0;
  width: 2px;
  height: 100%;
  background-color: currentColor;
}

.title span::before {
  left: 0;
  transform: rotate(-30deg);
}

.title span::after {
  right: 0;
  transform: rotate(30deg);
}

.btn-wrapper {
  width: 100%;
  margin: 1.25em auto 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  box-sizing: border-box;
}

.btn-wrapper>.btn-item {
  width: 100%;
  margin-bottom: 10px;
}

.btn-wrapper a.btn:not(:has(img)) {
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1.25;
  color: #ffffff;
  font-size: 1.5em;
  font-weight: bold;
  background-color: #e55503;
  border-bottom: 10px solid #8f2800;
  border-radius: 99px;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 1em 1.25em;
  text-align: center;
  text-decoration: none;
  transition: 0.3s;
}


.btn-wrapper a:hover {
  opacity: 0.75;
}

img,
video {
  width: 100%;
}

* {
  box-sizing: border-box
}

.widget-container {
  font-size: 14px;
  width: min(750px, 100%);
  margin-inline: auto;
}

@media (max-width: 500px) {
  .widget-container {
    font-size: 3vw;
  }
}

.widget-container>* {
  box-sizing: border-box;
}

button {
  cursor: pointer;
  border: solid 1px #000;
  display: block;
  width: 100%;
  text-align: center;
  background: #ffd1d5;
  padding: 1em;
  line-height: 1.5;
  position: relative;
  box-shadow: 0px 7px 0px 0px rgba(190, 190, 190, 0.4);
}

button::before {
  content: "";
  width: 6px;
  height: 6px;
  border-top: 2px solid #333;
  border-right: 2px solid #333;
  -webkit-transform: rotate(45deg);
  position: absolute;
  top: calc(50% - 3px);
  right: 20px;
  transform: rotate(135deg);
}

.toggle-item>*+* {
  margin-top: 1.5em;
}

.toggle-content {
  width: 90%;
  margin-inline: auto;
  opacity: 0;
  max-height: 0;
  overflow: hidden;
  transition: all 0.3s;
}

.toggle-content.active {
  opacity: 1;
  max-height: 9999px;
  overflow: visible;
}

.toggle-content>*+* {
  margin-top: 1.5em;
}

.toggle-content-title {
  font-size: 1.2em;
  border-block: solid 1px #000;
  padding: 0.5em 1em;
  box-sizing: border-box;
  text-align: center;
  margin-bottom: 1em;
}

.toggle-content-table {
  width: 100%;
  border-collapse: collapse;
  border-spacing: 0;
}

.toggle-content-table th,
.toggle-content-table td {
  font-weight: 400;
  text-align: left;
  padding: 0.5em;
  box-sizing: border-box;
  line-height: 1.25;
}

.toggle-content-table th {
  vertical-align: top;
  width: min(100px);
}

iframe {
  width: 100%;
}

.title {
  text-align: center;
  font-size: 27px;
}

.title span {
  display: inline-block;
  position: relative;
}

.title span::before,
.title span::after {
  content: "";
  display: inline-block;
  position: absolute;
  top: 0;
  width: 2px;
  height: 100%;
  background-color: #53adff;
}

.title span::before {
  left: -1em;
  transform: rotate(-30deg);
}

.title span::after {
  right: -1em;
  transform: rotate(30deg);
}

.lead {
  text-align: center;
  font-size: 20px;
  font-weight: bold;
  margin-top: 20px;
}

.btn-group {
  max-width: 600px;
  width: 100%;
  margin: 20px auto 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  box-sizing: border-box;
}

