}

.accordions-items-title span {
  font-size: 1.4em;
  width: fit-content;
  display: block;
  background: #44331f;
  color: #fff;
  padding: 0 1em;
  position: relative;
  margin: auto;
}

.accordions-items-title::before {
  content: "";
  width: 100%;
  height: 1px;
  background-color: #44331f;
  position: absolute;
  top: 50%;
  left: 0;
}

.accordions-items-content .title {
  display: flex;
  align-items: center;
  gap: 1em;
}

.accordions-items-content .num {
  font-family: serif;
  font-size: 3em;
  font-weight: 600;
  line-height: 1;
}

.accordions-items-content .text {
  flex-grow: 1;
  font-size: 1.2em;
}

.accordions-items-content.question {
  cursor: pointer;
}

.accordions-items-content.question.is-active+.answer {
  opacity: 1;
  max-height: 100%;
  pointer-events: all;
  animation: In 0.5s ease-in-out forwards;
}

.accordions-items-content.question.is-active .arrow-down::after {
  transform: rotate(-180deg);
}

.accordions-items-content.answer {
  opacity: 0;
  max-height: 0;
  overflow: hidden;
  pointer-events: none;
}

.accordions-items-content.answer.is-out {
  animation: Out 0.5s ease-in-out forwards !important;
}

.accordions-items-content.answer.is-out .answer-wrap {
  max-height: 0;
  padding: 0;
  margin: 0;
}

.accordions-items-content.answer .answer-wrap {
  padding: 1.5em;
  margin: 1em;
  background: #fff;
  border-radius: 15px;
  box-shadow: 7px 7px 0px 0px #ffe6cf;
  transition: 0.5s;
}

.accordions-items-content.answer .num {
  color: #E0801E;
}

.accordions-items-content.answer .title {
  border-bottom: 1px solid #000;
}

.accordions-items-content.answer .textarea {
  color: #000;
  padding: 0.5em;
}

@media (max-width: 500px) {
  .accordions {
    font-size: 3vw;
  }
}

.arrow-down::after {
  content: "▼";
  width: 0;
  height: 0;
  aspect-ratio: 1/1;
  background-color: #44331f;
  color: #fff;
  padding: 2em;
  clip-path: circle(50%);
  display: grid;
  place-content: center;
  font-size: 0.5em;
  transition: 0.5s;
}

@keyframes In {
  0% {
    opacity: 0;
    max-height: 0;
  }

  50% {
    opacity: 0;
    max-height: 100%;
  }

  100% {
    opacity: 1;
    max-height: 100%;
  }
}

@keyframes Out {
  0% {
    opacity: 0;
    max-height: 100%;
  }

  25% {
    opacity: 0;
    max-height: 100%;
  }

  75% {
    opacity: 0;
    max-height: 100%;
  }

  100% {
    opacity: 0;
    max-height: 0;
  }
}

