.actions {
  position: absolute;
  list-style: none inside none;
  margin: 0 0 0 0;
  padding: 0;
  width: auto;
  float: left;
  background-color: transparent;
  top: 8px;
  left: 8px;
  z-index: 1;
  width: 40px;
  height: 40px;
  border-radius: 50%;
}

.actions li {
  position: absolute;
  display: block;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  box-shadow: 0 2px 10px 0 rgba(0, 0, 0, 0.16), 0 2px 5px 0 rgba(0, 0, 0, 0.26);
  margin: 0;
  background: #212121;
  color: #ffffff;
  transition: all 0.3s;
  transform: scale(0.3);
}
.actions li:nth-child(1) {
  background: #ff9800;
}
.actions li:nth-child(2) {
  background: #2196f3;
}
.actions li:nth-child(3) {
  background: #ffeb3b;
}
.actions li:nth-child(4) {
  background: #e91e63;
}
.actions li:nth-child(5) {
  background: #4caf50;
}
.actions li a {
  background: inherit;
  color: inherit;
  display: flex;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  line-height: 40px;
  align-items: center;
  justify-content: center;
}

.actions li a .icon {
  width: 50%;
  height: auto;
}

.actions li a .icon img {
