}

.action-button.active {
  box-shadow: 0 17px 50px 0 rgba(0, 0, 0, 0.19), 0 12px 15px 0 rgba(0, 0, 0, 0.24);
}

.action-button.active ~ .actions li {
  transition: all 0.3s;
  transform: scale(1);
}
.action-button.active ~ .actions li:nth-child(1) {
