/* ボタンの箱 */
.childrenBtn {
  position: absolute;
  /* 配置位置（下基準） */
  bottom: 20px;
  /* 配置位置（左基準） */
  left: 50%;
  /* 位置調整（X方向） */
  transform: translateX(-50%);
  /* 横幅 */
  width: 90%;
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: flex-start;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: flex-start;
  flex-wrap: wrap;
}

/* ボタン */
.btn {
  /* 横幅（(全体の横幅 / ボタン個数) - 左右余白）
        　　※ボタン個数を増減する場合は「2」を編集してください */
  width: calc((100% / 2) - 10px);
  /* 外側の余白 */
  margin: 10px 5px 0;
  display: block;
  /* 装飾 */
  text-decoration: none;
  /* 角丸
         ※ボタンに角丸がある場合、もしくは画像ボタンで角丸がある場合は以下を適宜設定してください。
         「shine」アニメーションを入れた場合、border-radiusが適宜設定されてないと四隅が綺麗に角丸になりません。 */
  border-radius: 10px;
  position: relative;
  outline: none;
  overflow: hidden;
  z-index: 2;
}

/* ボタンが画像の場合 */
.btn img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}

/* ボタンがテキストの場合 */
.btn .textBtn {
  /* 横幅（右の矢印分を引く） */
  width: calc(100% - 40px);
  /* 高さ */
  height: auto;
  /* 文字色 */
  color: #fff;
  /* 文字の大きさ */
  font-size: 28px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の位置 */
  text-align: center;
  display: inline-block;
  /* 内側の余白｜上｜右｜下｜左｜ */
  padding: 10px 40px 10px 0;
  position: relative;
}

/* レスポンシブ設定（初期600px以下） */
@media screen and (max-width:600px) {

  /* ボタンがテキストの場合 */
  .btn .textBtn {
    /* 文字の大きさ */
    font-size: 20px;
  }
}

/* テキストボタンの右側の矢印の白丸 */
.btn .textBtn:before {
  content: "";
  /* 横幅 */
  width: 30px;
  /* 高さ */
  height: 30px !important;
  /* 背景色 */
  background: #fff;
  /* 角丸（円にするため） */
  border-radius: 15px;
  position: absolute;
  /* 配置位置（上基準） */
  top: 50%;
  /* 配置位置（右基準） */
  right: 10px;
  /* 位置調整（Y方向） */
  transform: translateY(-50%);
  /* 内側の影｜X方向｜Y方向｜ぼかし｜色｜内側｜ */
  box-shadow: 0px 2px 1px #ccc inset;
}

/* テキストボタンの右側の矢印の三角形 */
.btn .textBtn::after {
  content: "";
  position: absolute;
  /* 配置位置（上基準） */
  top: 51%;
  /* 配置位置（右基準） */
  right: 19px;
  /* 位置調整（Y方向） */
  transform: translateY(-51%);
  /* 横幅 */
  width: 0;
  /* 高さ */
  height: 0 !important;
  border-style: solid;
  /* 三角形の大きさ */
  border-width: 7.5px 0 7.5px 10px;
  z-index: 1;
}

/* 最初のボタン */
.btn:first-of-type .textBtn {
  /* 背景色 */
  background: linear-gradient(180deg, #92cfec 0%, #2290c3 100%);
}

/* 最初のボタンの右側の矢印の色 */
.btn:first-of-type .textBtn:after {
  border-color: transparent transparent transparent #2290c3;
}

/* 2番目のボタン */
.btn:nth-of-type(2) .textBtn {
  /* 背景色 */
  background: linear-gradient(180deg, #eb9fc9 0%, #de60a5 100%);
}

/* 2番目のボタンの矢印の色 */
.btn:nth-of-type(2) .textBtn:after {
  border-color: transparent transparent transparent #de60a5;
}

/* 3番目以降のボタンを使用する場合は以下をご利用ください */
/* 3番目のボタン */
/* .btn:nth-of-type(3) .textBtn {
      background: linear-gradient(180deg, #eb9fc9 0%, #de60a5 100%);
    } */

/* 3番目のボタンの矢印の色 */
/* .btn:nth-of-type(3) .textBtn:after {
      border-color: transparent transparent transparent #de60a5;
    } */

/* マウスホバー時、光る四角の設定 */
.shine .btn:hover:before {
  content: '';
  position: absolute;
  /* 配置位置（上基準） */
  top: 0;
  /* 配置位置（左基準） */
  left: -75%;
  /* 横幅 */
  width: 50%;
  /* 高さ */
  height: 100%;
  /* 背景色 */
  background: linear-gradient(to right, rgba(255, 255, 255, 0) 0%, rgba(255, 255, 255, .3) 100%);
  /* 斜め */
  transform: skewX(-25deg);
  z-index: 2;
}

/* マウスホバー時の光る動き */
.shine .btn:hover::before {
  /* アニメーション名 */
  animation-name: shine;
  /* 1回のサイクルに要する時間 */
  animation-duration: 0.7s;
  /* 実行回数
        　　infinite = ホバー中
        　　1　= 1回のみ */
  animation-iteration-count: infinite;
}

.big .btn:hover {
  /* アニメーション名 */
  animation-name: big;
  /* 1回のサイクルに要する時間 */
  animation-duration: 0.7s;
  /* アニメーション実行後の状態
         forwards = 100%の状態
         backwards = 0%の状態 */
  animation-fill-mode: forwards;
  /* 実行回数
        　　infinite = ホバー中
        　　1　= 1回のみ */
  animation-iteration-count: infinite;
}

.arrowMove .btn:hover .textBtn:after {
  /* アニメーション名 */
  animation-name: arrowmove;
  /* 1回のサイクルに要する時間 */
  animation-duration: 0.7s;
  /* アニメーション実行後の状態
         forwards = 100%の状態
         backwards = 0%の状態 */
  animation-fill-mode: forwards;
  /* 実行回数
        　　infinite = ホバー中
        　　1　= 1回のみ */
  animation-iteration-count: infinite;
}

/* 光るアニメーションの動き */
@keyframes shine {
  100% {
    /* 配置位置（左基準） */
    left: 125%;
  }
}

/* 拡大するアニメーションの動き */
@keyframes big {
  0% {
    /* 大きさ
           1 = 等倍 */
    transform: scale(1);
  }

  50% {
    transform: scale(1.05);
  }

  100% {
    transform: scale(1);
  }
}

/* 矢印が動くアニメーションの動き */
@keyframes arrowmove {
  0% {
    /* 配置位置（右基準） */
    right: 19px;
  }

  25% {
    right: 15px;
  }

  75% {
    right: 22px;
  }

  100% {
    right: 19px;
  }
}

