/* アニメーションの詳細設定 */
@keyframes puyoBtn {

  /* タイミング */
  0% {
    /* ボタンの拡大、縮小
    ・値が1つ = X＆Y軸
    ・値が2つ = X軸, Y軸 */
    transform: scale(1.09);
  }

  10% {
    transform: scale(1.09);
  }

  30% {
    transform: scale(1.01);
  }

  40% {
    transform: scale(1.01);
  }

