   /*水平方向に「テキストがあるエリア」と「画像があるエリア」に間隔を配置する方法。
   space-around = 均等配置して両端に間隔を置く
	space-between = 均等配置してエリアの間に間隔を置く
	space-evenly = 均等配置して各アイテム周りに間隔を置く*/
   justify-content: space-evenly;
   /*垂直方向に「テキストがあるエリア」と「画像があるエリア」の配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
   align-items: center;
 }


 /*テキストがあるエリア*/
 .flex-left {
   display: flex;
   /*「テキストがあるエリア」のコンテンツの主軸となる方向を定義。
      row = デフォルト、水平方向を基準とし、左から右に配置
      row-reverse = 水平方向を基準とし、右から左に配置
      column =  垂直方向を基準とし、上から下に配置
      column-reverse = 垂直方向を基準とし、下から上に配置*/
   flex-direction: column;
   /*垂直方向に間隔を配置する方法。
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
   justify-content: center;
   /*水平方向に配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
   align-items: flex-start;
   /*横幅*/
   width: 45%;
   box-sizing: border-box;
 }


 /*画像があるエリア*/
 .flex-right {
   display: flex;
   /*主軸となる方向を定義。
      row = デフォルト、水平方向を基準とし、左から右に配置
      row-reverse = 水平方向を基準とし、右から左に配置
      column =  垂直方向を基準とし、上から下に配置
      column-reverse = 垂直方向を基準とし、下から上に配置*/
   flex-direction: column;
   /*水平方向に間隔を配置する方法。
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
