  /*水平方向の字間のスペース*/
  letter-spacing: 0.1em;
  /*ボタンの高さ*/
  line-height: 1.5;
  /*ボタン内側の余白。上下｜左右*/
  padding: 1rem 4rem;
  /*角を丸くする*/
  border-radius: 0.5rem;
  position: relative;
  /*カーソルがボタンに触れた時に指になる*/
  cursor: pointer;
  /*カーソルがボタンに触れた時のアニメーションの速さ*/
  transition: all 0.3s;
  /*文字の位置*/
  text-align: center;
  /*文字の飾り*/
  text-decoration: none;
  box-sizing: border-box;
}

 a.btn:hover {
  /*ボタンの上にカーソルを置いた時の背景色を指定*/
  background: #55c55a;
}

.footer {
  /*表示方法（fixed=固定）*/
