  /*表示位置（下基準）*/
  bottom: 0;
  /*表示位置（左基準）*/
  left: 0;
  /*横幅*/
  width: 100%;
  /*重ね合わせの順番*/
  z-index: 1000;
}

.footer-inner {
  display: flex;
  /*垂直方向にの配置位置を設定。
     center = 中央配置
     flex-start = 先頭にまとめる
     flex-end = 末尾にまとめる*/
  align-items: center;
  /*水平方向に間隔を配置する方法。
  center = 真ん中
     space-around = 均等配置して両端に間隔を置く
     space-between = 均等配置してエリアの間に間隔を置く
     space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /*背景色を変えられます。 色コード見本→ https://www.colordic.org/*/
  background-color: #FADCE2;
}

.text {
  /*文字エリアの最大幅をパーセンテージで設定できます*/
  max-width: 80%;
  /*文字サイズ*/
  font-size: 16px;
  /*文字の色*/
  color: #000;
  /*文字の太さ。太字はbold、標準の太さはnormal*/
  font-weight: bold;
  /*水平方向の字間のスペース*/
  letter-spacing: 0.05em;
  /* 行間調整 */
  line-height: 1.75;
  /*文字の水平方向の配置。左寄せはleft、真ん中はcenter、右寄せはright*/
  text-align: left;
  /*文字周りの余白。上下｜左右*/
  padding: 0 10px;
}



/*画像の設定*/
img.image {
  /* 画像の幅を変える場合は下記数値を変更ください*/
  width: 100px;
  /*高さ*/
  height: auto;
  /*外側の上下左右余白*/
  margin: 0;
  /*要素の縦方向の位置*/
  vertical-align: middle;
}

 .footer {
  /*表示設定（fixed=固定）*/
  position: fixed;
  /*表示位置（下基準）*/
  bottom: 0;
  /*表示位置（左基準）*/
  left: 0;
  /*表示位置（右基準）*/
  right: 0;
  /*横幅*/
  width: 100%;
  /*重なりの順番*/
  z-index: 1000;
}

 .footer-inner {
  display: flex;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: center;
  /*水平方向に間隔を配置する方法。
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: space-around;
  /* 背景色が不要なときは下記1行を削除。背景色を変えられます。 
   色コード見本→ https://www.colordic.org/*/
  background-color: #00d4c8;
}



/*画像の設定*/
img.image {
  /* 画像の幅を変える場合は下記数値を変更ください*/
  width: 200px;
  /*高さ*/
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto !important;
}

.btn-area {
  /*ボタン周りの余白上下｜左右*/
  margin: 1em 0;
  display: flex;
  /*ボタンの水平方向配置。左寄せは flex-start 、真ん中寄せは center、右寄せはflex-end*/
  justify-content: center;
}

.btn-square {
  /*横幅サイズを変更する場合は下記autoを20%から100%で変更できます*/
  width: auto;
  position: relative;
  /*ボタン正面内側の余白。上下｜左右*/
  padding: 0.35em 1em;
  /*ボタン正面の背景色*/
  background: #668ad8;
  /*ボタンの文字色*/
  color: #FFF;
  /*文字の飾り*/
  text-decoration: none;
  /*文字の位置*/
  text-align: center;
  box-sizing: border-box;
}



/*ボタンの立体部分*/
.btn-square:before {
  content: "";
  /*表示方法（absolute=絶対配置、親要素の領域から配置する）*/
  position: absolute;
  /*表示位置（上基準）*/
  top: -16px;
  /*表示位置（左基準）*/
  left: 0;
  /*横幅*/
  width: calc(100% - 16px);
  /*高さ（下記のborderで立体部分を表示しているため、高さは0とする）*/
  height: 0;
  /*立体部分｜線種｜太さ（立体の大きさ）｜色（下記のborder-bottom-colorを反映）｜*/
  border: solid 8px transparent;
  /*ボタン上面の色（正面の色より明るくすると立体的に見えます）*/
  border-bottom-color: #8eacec;
}



/*ボタンをクリックしたとき*/
.btn-square:active {
  /*押したときの余白。上下｜左右*/
  padding: 0.32em 0.9em;
  /*垂直方向への移動*/
  transform: translateY(-2px);
}



/*ボタンをクリックした時の立体部分*/
.btn-square:active:before {
  /*横幅（通常時と比較して小さくすると、ボタンクリック時に押し込んだ感じが出ます）*/
  width: calc(100% - 12px);
  top: -12px;
  border-width: 6px;
}
